// =====================================================================
//  PARAMÈTRES DU RADAR : c'est le seul nœud à modifier.
//  Source : ONU Comtrade (importations déclarées par les douanes de chaque pays).
// =====================================================================

// 1) Où envoyer le résumé et où ranger les résultats
const email = 'ton.email@exemple.com';
const googleSheetUrl = 'https://docs.google.com/spreadsheets/d/COLLE_ICI_L_ID_DE_TA_FEUILLE/edit';

// 2) Ta ferme : sert à écrire le brief de chaque signal (« à retenir » et « que faire »).
//    Règle : uniquement des cycles courts. Un produit dont le cycle dépasse cycleMaxMois
//    n'est jamais proposé comme projet pour la ferme, seulement en courtage.
const ferme = {
  lieu: 'Douala',
  surfaceHa: 18,
  cycleMaxMois: 5, // 4 à 5 mois maximum avant la première vente
  demarrage: 'décembre 2026',
};
const fcfaParDollar = 578; // taux du 30/09/2026 (1 € = 655,957 FCFA) : à mettre à jour de temps en temps

// 3) Tes produits (code douanier SH à 4 ou 6 chiffres), avec ce qu'ils représentent pour ta ferme à Douala.
//    statut    : 'je produis' | 'je peux produire' | 'je peux sourcer' | '' (simple surveillance)
//    faisable  : 'oui' | 'moyen' | 'non' : est-ce adapté au climat de Douala ?
//    cycleMois : mois avant la première vente (comparé à ferme.cycleMaxMois)
//    projet    : le projet concret ; delai : en clair ; etape : la prochaine action
//    zone      : d'où viennent les producteurs quand ce n'est pas pour toi (« du Nord »…), pour le courtage
const produits = [
  // --- Cycles courts adaptés à Douala : ce que tu peux produire ---
  { hs: '0702', nom: 'Tomates', statut: 'je peux produire', faisable: 'oui', cycleMois: 3, projet: 'tomates (de préférence en saison sèche, avec irrigation)', delai: '3 mois', etape: "choisir des variétés résistantes à la chaleur et aux maladies, et prévoir l'irrigation pour la saison sèche (décembre à février)" },
  { hs: '0709', nom: 'Autres légumes frais (piment, gombo, aubergine…)', statut: 'je peux produire', faisable: 'oui', cycleMois: 3, projet: 'légumes (piment, gombo, aubergine, poivron)', delai: '2 à 3 mois', etape: 'repérer les grossistes et revendeuses des marchés de Douala (Sandaga…) et leurs prix selon la saison' },
  { hs: '0707', nom: 'Concombres', statut: 'je peux produire', faisable: 'oui', cycleMois: 2.5, projet: 'concombres', delai: '2 à 3 mois', etape: 'trouver 2 ou 3 acheteurs réguliers (supermarchés, restaurants, revendeuses)' },
  { hs: '0807', nom: 'Pastèques et melons', statut: 'je peux produire', faisable: 'oui', cycleMois: 3, projet: 'pastèques (saison sèche)', delai: '3 mois', etape: "planter en début de saison sèche et prévoir l'irrigation" },
  { hs: '0904', nom: 'Piment et poivre séchés', statut: 'je peux produire', faisable: 'oui', cycleMois: 4, projet: 'piment (frais ou séché)', delai: '3 à 4 mois', etape: 'tester le séchage du piment, qui se garde et se vend loin (Gabon, Nigeria)' },
  { hs: '0714', nom: 'Patates douces, manioc et tubercules', statut: 'je peux produire', faisable: 'oui', cycleMois: 4, projet: 'patate douce (le manioc, 9 à 12 mois, est trop long pour toi)', delai: '3 à 5 mois', etape: "trouver des boutures de variétés améliorées (IRAD) et des acheteurs avant de planter" },
  { hs: '1005', nom: 'Maïs', statut: 'je peux produire', faisable: 'moyen', cycleMois: 3.5, projet: 'maïs (frais en épis, ou en grain pour la provende)', delai: '3 à 4 mois', note: "l'humidité de Douala complique le séchage et le stockage du grain ; le maïs frais en épis se vend sans séchage", zone: "de l'Ouest et du Nord" },
  { hs: '0207', nom: 'Viande de volaille', statut: 'je peux produire', faisable: 'oui', cycleMois: 1.5, projet: 'poulets de chair en bâtiment (moins de 0,5 ha)', delai: '45 jours par bande', etape: 'chiffrer une bande de 500 poulets : poussins de couvoir agréé, aliment, vaccins, puis trouver 2 ou 3 acheteurs (restaurants, revendeuses) avant de démarrer' },
  { hs: '0407', nom: 'Œufs', statut: 'je peux produire', faisable: 'oui', cycleMois: 5, projet: 'poules pondeuses en bâtiment', delai: '5 mois (début de ponte), puis des œufs chaque jour pendant environ un an', etape: 'chiffrer un lot de 1 000 pondeuses et repérer les boulangeries et supermarchés acheteurs' },
  { hs: '230990', nom: 'Provende (aliments pour volaille)', statut: '', faisable: 'oui', cycleMois: 1, projet: "fabriquer l'aliment de tes propres poulets (maïs, soja, tourteaux)", delai: '1 à 2 mois', etape: "à envisager seulement après avoir lancé les poulets, pour baisser ton premier poste de coût" },
  { hs: '1106', nom: 'Farines de manioc et gari', statut: '', faisable: 'oui', cycleMois: 1, projet: 'petite unité de gari en achetant le manioc', delai: 'quelques semaines', etape: 'chiffrer une râpeuse, une presse et un torréfacteur, et tester la vente de gari à Douala' },
  { hs: '1006', nom: 'Riz', statut: '', faisable: 'moyen', cycleMois: 4.5, projet: 'riz de bas-fonds avec décortiqueuse', delai: '4 à 5 mois', note: 'le riz importé arrive très bon marché ; il faut de la mécanisation pour rivaliser', zone: 'du Nord et du Nord-Ouest (Ndop)' },
  { hs: '1202', nom: 'Arachides', statut: '', faisable: 'moyen', cycleMois: 3.5, projet: 'arachide', delai: '3 à 4 mois', note: 'pousse mieux en savane, mais possible sur sol sableux', zone: 'du Nord et du Centre' },
  { hs: '1201', nom: 'Soja', statut: '', faisable: 'moyen', cycleMois: 4, projet: 'soja (pour la provende)', delai: '4 mois', note: 'mieux adapté aux savanes', zone: "de l'Adamaoua et du Nord" },
  { hs: '0713', nom: 'Haricots et niébé secs', statut: '', faisable: 'moyen', cycleMois: 3, projet: 'niébé ou haricot', delai: '2 à 3 mois', note: "l'humidité favorise les maladies", zone: "de l'Ouest et du Nord" },
  // --- Cycles trop longs pour toi (plus de 5 mois) : courtage seulement ---
  { hs: '0303', nom: 'Poisson congelé', statut: '', faisable: 'oui', cycleMois: 7, projet: 'pisciculture (silure, tilapia)', delai: '6 à 8 mois', zone: 'des fermes piscicoles du Littoral et du Centre' },
  { hs: '0803', nom: 'Bananes et plantains', statut: '', faisable: 'oui', cycleMois: 12, projet: 'plantain', delai: '10 à 14 mois', zone: 'du Moungo et du Littoral' },
  { hs: '0910', nom: 'Gingembre, curcuma et épices', statut: '', faisable: 'oui', cycleMois: 9, projet: 'gingembre', delai: '8 à 10 mois', zone: 'de tout le pays' },
  { hs: '0804', nom: 'Ananas, avocats, mangues', statut: '', faisable: 'oui', cycleMois: 15, projet: 'ananas', delai: '14 à 18 mois', zone: 'du Littoral et du Centre' },
  { hs: '1511', nom: 'Huile de palme', statut: '', faisable: 'oui', cycleMois: 36, projet: 'palmeraie', delai: '3 ans', zone: 'des huileries et planteurs du Littoral et du Sud-Ouest' },
  { hs: '1801', nom: 'Fèves de cacao', statut: '', faisable: 'moyen', cycleMois: 48, projet: 'cacaoyère', delai: '3 à 5 ans', note: 'la traçabilité est exigée pour l’Union européenne', zone: 'du Centre, du Sud et du Sud-Ouest' },
  { hs: '0901', nom: 'Café', statut: '', faisable: 'moyen', cycleMois: 36, projet: 'caféier robusta', delai: '3 ans', zone: 'du Moungo et de l’Ouest' },
  { hs: '1108', nom: 'Amidons (dont amidon de manioc)', statut: '', faisable: 'moyen', cycleMois: 12, projet: 'amidon de manioc', delai: '1 an', note: 'demande un procédé industriel', zone: 'des bassins de manioc du Centre et de l’Est' },
  // --- Pas adaptés à Douala ---
  { hs: '0703', nom: 'Oignons, ail, échalotes', statut: '', faisable: 'non', cycleMois: 4, note: 'trop humide à Douala', zone: 'du Nord et de l’Extrême-Nord' },
  { hs: '0701', nom: 'Pommes de terre', statut: '', faisable: 'non', cycleMois: 4, note: "il faut l'altitude", zone: "de l'Ouest et du Nord-Ouest" },
  { hs: '0801', nom: 'Noix de cajou et noix de coco', statut: '', faisable: 'non', cycleMois: 48, note: 'le cajou pousse dans le Nord, et le cocotier met des années', zone: 'du Nord' },
  { hs: '1207', nom: 'Sésame, karité et autres graines', statut: '', faisable: 'non', cycleMois: 4, note: 'cultures de savane', zone: 'du Nord et de l’Extrême-Nord' },
  { hs: '1701', nom: 'Sucre', statut: '', faisable: 'non', cycleMois: 12, note: "c'est une industrie (canne à sucre à très grande échelle)", zone: '' },
];

// 4) Les marchés à surveiller (code pays de l'ONU). « dans » sert à écrire les briefs (« au Congo », « aux Pays-Bas »…).
//    proximite : 1 = très facile d'accès (route, zone CEMAC) … 0.3 = loin ou normes exigeantes
const pays = [
  { code: 120, nom: 'Cameroun', dans: 'au Cameroun', zone: 'Cameroun', proximite: 1 },
  { code: 266, nom: 'Gabon', dans: 'au Gabon', zone: 'CEMAC', proximite: 0.9 },
  { code: 178, nom: 'Congo', dans: 'au Congo', zone: 'CEMAC', proximite: 0.9 },
  { code: 226, nom: 'Guinée équatoriale', dans: 'en Guinée équatoriale', zone: 'CEMAC', proximite: 0.9 },
  { code: 148, nom: 'Tchad', dans: 'au Tchad', zone: 'CEMAC', proximite: 0.9 },
  { code: 140, nom: 'Centrafrique', dans: 'en Centrafrique', zone: 'CEMAC', proximite: 0.8 },
  { code: 566, nom: 'Nigeria', dans: 'au Nigeria', zone: 'Afrique', proximite: 0.8 },
  { code: 180, nom: 'RD Congo', dans: 'en RD Congo', zone: 'Afrique', proximite: 0.6 },
  { code: 562, nom: 'Niger', dans: 'au Niger', zone: 'Afrique', proximite: 0.6 },
  { code: 204, nom: 'Bénin', dans: 'au Bénin', zone: 'Afrique', proximite: 0.6 },
  { code: 768, nom: 'Togo', dans: 'au Togo', zone: 'Afrique', proximite: 0.5 },
  { code: 288, nom: 'Ghana', dans: 'au Ghana', zone: 'Afrique', proximite: 0.5 },
  { code: 384, nom: "Côte d'Ivoire", dans: "en Côte d'Ivoire", zone: 'Afrique', proximite: 0.5 },
  { code: 686, nom: 'Sénégal', dans: 'au Sénégal', zone: 'Afrique', proximite: 0.5 },
  { code: 504, nom: 'Maroc', dans: 'au Maroc', zone: 'Afrique', proximite: 0.4 },
  { code: 12, nom: 'Algérie', dans: 'en Algérie', zone: 'Afrique', proximite: 0.4 },
  { code: 251, nom: 'France', dans: 'en France', zone: 'Hors Afrique', proximite: 0.3 },
  { code: 56, nom: 'Belgique', dans: 'en Belgique', zone: 'Hors Afrique', proximite: 0.3 },
  { code: 528, nom: 'Pays-Bas', dans: 'aux Pays-Bas', zone: 'Hors Afrique', proximite: 0.3 },
  { code: 276, nom: 'Allemagne', dans: 'en Allemagne', zone: 'Hors Afrique', proximite: 0.3 },
  { code: 380, nom: 'Italie', dans: 'en Italie', zone: 'Hors Afrique', proximite: 0.3 },
  { code: 826, nom: 'Royaume-Uni', dans: 'au Royaume-Uni', zone: 'Hors Afrique', proximite: 0.3 },
  { code: 842, nom: 'États-Unis', dans: 'aux États-Unis', zone: 'Hors Afrique', proximite: 0.3 },
  { code: 156, nom: 'Chine', dans: 'en Chine', zone: 'Hors Afrique', proximite: 0.3 },
  { code: 784, nom: 'Émirats arabes unis', dans: 'aux Émirats arabes unis', zone: 'Hors Afrique', proximite: 0.3 },
];

// 5) Réglages
const nbAnnees = 5; // années d'historique demandées (la plus récente = l'an dernier)
const topN = 15; // nombre d'opportunités détaillées dans l'email (2 pays maximum par produit)

// 6) Facultatif : clé gratuite ONU Comtrade (comtradedeveloper.un.org) pour dépasser le quota de la version sans clé.
//    Laisse '' si tu n'en as pas.
const cleComtrade = '';
const urlComtrade = cleComtrade
  ? 'https://comtradeapi.un.org/data/v1/get/C/A/HS'
  : 'https://comtradeapi.un.org/public/v1/preview/C/A/HS';

return [
  { json: { email, googleSheetUrl, ferme, fcfaParDollar, produits, pays, nbAnnees, topN, cleComtrade, urlComtrade } },
];

// Fabrique les adresses à interroger chez ONU Comtrade.
// Version sans clé : une seule année par requête, 500 lignes maximum par réponse, et un quota d'appels.
const p = $input.first().json;
const derniereAnnee = new Date().getFullYear() - 1;
const annees = Array.from({ length: p.nbAnnees }, (_, i) => derniereAnnee - i);
const codesPays = p.pays.map((x) => x.code).join(',');

// Autant de produits par requête que possible sans dépasser 500 lignes
const parLot = Math.max(1, Math.floor(450 / p.pays.length));
const lots = [];
for (let i = 0; i < p.produits.length; i += parLot) {
  lots.push(p.produits.slice(i, i + parLot).map((x) => x.hs).join(','));
}

const requetes = [];
for (const annee of annees) {
  for (const codesProduits of lots) {
    const url = `${p.urlComtrade}?reporterCode=${codesPays}&period=${annee}&partnerCode=0&cmdCode=${codesProduits}&flowCode=M`;
    requetes.push({ json: { annee, url: p.cleComtrade ? `${url}&subscription-key=${encodeURIComponent(p.cleComtrade)}` : url } });
  }
}
return requetes;

// Calcule un score de 0 à 100 pour chaque couple pays + produit.
//   35 % taille du marché : 1 M$ d'importations par an = 0, 1 milliard $ = maximum
//   25 % croissance       : −10 %/an = 0, +30 %/an = maximum (sur 3 ans au plus)
//   20 % proximité        : valeur « proximite » du pays dans Paramètres
//   20 % ta position      : « je produis » > « je peux produire » > « je peux sourcer » > surveillance
const p = $('Paramètres').first().json;
const paysParCode = Object.fromEntries(p.pays.map((x) => [String(x.code), x]));
const produitParCode = Object.fromEntries(p.produits.map((x) => [x.hs, x]));
const noteStatut = { 'je produis': 1, 'je peux produire': 0.7, 'je peux sourcer': 0.5 };
const anneeCourante = new Date().getFullYear();
const aujourdhui = $now.toISODate();
const borne = (x, min, max) => Math.min(max, Math.max(min, x));

// 1) Regrouper les chiffres par pays + produit + année
const series = {};
for (const item of $input.all()) {
  const lignes = item.json.data;
  if (!Array.isArray(lignes)) continue; // requête refusée ou vide : on continue avec le reste
  for (const l of lignes) {
    if (l.partnerCode !== 0 || l.flowCode !== 'M' || !l.primaryValue) continue;
    const cle = `${l.reporterCode}-${l.cmdCode}`;
    const s = (series[cle] ??= { codePays: l.reporterCode, hs: l.cmdCode, annees: {} });
    const deja = s.annees[l.refYear];
    if (!deja || l.primaryValue > deja.valeur) {
      s.annees[l.refYear] = { valeur: l.primaryValue, poids: l.netWgt };
    }
  }
}

// 2) Score de chaque série
const resultats = [];
for (const [cle, s] of Object.entries(series)) {
  const pays = paysParCode[String(s.codePays)];
  const produit = produitParCode[s.hs];
  if (!pays || !produit) continue;

  const annees = Object.keys(s.annees).map(Number).sort((a, b) => b - a);
  const derniere = annees[0];
  const valeur = s.annees[derniere].valeur;
  const base = annees.filter((a) => a < derniere && a >= derniere - 3).pop();
  const croissance = base ? Math.pow(valeur / s.annees[base].valeur, 1 / (derniere - base)) - 1 : null;
  const poids = s.annees[derniere].poids;

  const noteTaille = borne((Math.log10(valeur) - 6) / 3, 0, 1);
  const noteCroissance = croissance === null ? 0.4 : borne((croissance + 0.1) / 0.4, 0, 1);
  const noteProximite = borne(Number(pays.proximite) || 0, 0, 1);
  const notePosition = noteStatut[produit.statut] ?? 0.2;
  const score = Math.round(
    100 * (0.35 * noteTaille + 0.25 * noteCroissance + 0.2 * noteProximite + 0.2 * notePosition),
  );

  let typeSignal = 'Exporter ou faire du courtage en Afrique';
  if (pays.zone === 'Cameroun') typeSignal = 'Remplacer des importations au Cameroun';
  if (pays.zone === 'Hors Afrique') typeSignal = "Exporter hors d'Afrique";

  resultats.push({
    cle,
    score,
    type_signal: typeSignal,
    pays: pays.nom,
    zone: pays.zone,
    produit: produit.nom,
    code_hs: s.hs,
    mon_statut: produit.statut || '',
    annee: derniere,
    imports_usd: Math.round(valeur),
    croissance_annuelle_pct: croissance === null ? '' : Math.round(croissance * 1000) / 10,
    prix_usd_kg: poids > 0 ? Math.round((valeur / poids) * 100) / 100 : '',
    donnees_anciennes: derniere < anneeCourante - 3 ? 'oui' : 'non',
    code_pays: s.codePays,
    date_maj: aujourdhui,
  });
}

if (!resultats.length) {
  throw new Error("Aucune donnée reçue d'ONU Comtrade (limite de requêtes atteinte ?). Relance dans quelques minutes.");
}
resultats.sort((a, b) => b.score - a.score);
return resultats.map((json) => ({ json }));

// Choisit les pistes détaillées dans l'email :
// 1) jusqu'à 5 places réservées aux produits que TA ferme peut faire (adaptés à Douala, cycle court,
//    au moins 1 M$ d'importations) ;
// 2) le reste par score, avec au plus 2 pays par produit et 4 marchés hors d'Afrique ;
// les produits sans aucune action possible pour toi (ex. sucre industriel) sont laissés de côté.
const p = $('Paramètres').first().json;
const fiches = Object.fromEntries(p.produits.map((x) => [x.hs, x]));
const pourMoi = (f) => f.faisable && f.faisable !== 'non' && (f.cycleMois ?? 99) <= p.ferme.cycleMaxMois;
const tous = $input.all();

const parProduit = {};
let horsAfrique = 0;
const choisis = new Set();
const prendre = (item) => {
  const o = item.json;
  parProduit[o.code_hs] = (parProduit[o.code_hs] || 0) + 1;
  if (o.zone === 'Hors Afrique') horsAfrique++;
  choisis.add(item);
};
const possible = (item) => {
  const o = item.json;
  const f = fiches[o.code_hs] || {};
  if (choisis.has(item) || (parProduit[o.code_hs] || 0) >= 2) return false;
  if (o.zone === 'Hors Afrique' && horsAfrique >= 4) return false;
  return !(f.faisable === 'non' && !f.zone);
};

// Places réservées : d'abord le marché camerounais (remplacer des importations), puis les voisins africains
const pourLaFerme = tous
  .filter((item) => item.json.zone !== 'Hors Afrique' && item.json.imports_usd >= 1e6 && pourMoi(fiches[item.json.code_hs] || {}))
  .sort((a, b) => (a.json.zone === 'Cameroun' ? 0 : 1) - (b.json.zone === 'Cameroun' ? 0 : 1));
for (const item of pourLaFerme) {
  if (choisis.size >= Math.min(5, p.topN)) break;
  if (possible(item)) prendre(item);
}
for (const item of tous) {
  if (choisis.size >= p.topN) break;
  if (possible(item)) prendre(item);
}
return tous.filter((item) => choisis.has(item));

// Regroupe les opportunités du top par produit et par année : une seule requête Comtrade
// couvre jusqu'à 4 pays, ce qui économise le quota d'appels de la version gratuite.
const p = $('Paramètres').first().json;
const groupes = {};
for (const item of $input.all()) {
  const o = item.json;
  (groupes[`${o.annee}|${o.code_hs}`] ??= []).push(o.code_pays);
}
const requetes = [];
for (const [cle, codesPays] of Object.entries(groupes)) {
  const [annee, hs] = cle.split('|');
  for (let i = 0; i < codesPays.length; i += 4) {
    const url = `${p.urlComtrade}?reporterCode=${codesPays.slice(i, i + 4).join(',')}&period=${annee}&cmdCode=${hs}&flowCode=M`;
    requetes.push({ json: { url: p.cleComtrade ? `${url}&subscription-key=${encodeURIComponent(p.cleComtrade)}` : url } });
  }
}
return requetes;

// Pour chaque opportunité du top : qui vend aujourd'hui à ce pays, quelle part vient d'Afrique et du Cameroun,
// puis le brief : ce qu'il faut retenir et ce que tu peux en faire avec ta ferme.
const top = $('Top N').all();
const lignesFournisseurs = $('Comtrade : qui fournit ?')
  .all()
  .flatMap((r) => (Array.isArray(r.json.data) ? r.json.data : []));
const noms = {};
for (const r of $input.first().json.results || []) noms[String(r.id)] = r.text;

// Codes ONU des pays africains
const AFRIQUE = new Set([
  12, 24, 72, 108, 120, 132, 140, 148, 174, 178, 180, 204, 226, 231, 232, 262, 266, 270, 288, 324, 384,
  404, 426, 430, 434, 450, 454, 466, 478, 480, 504, 508, 516, 562, 566, 624, 646, 654, 678, 686, 690,
  694, 706, 710, 711, 716, 728, 729, 732, 748, 768, 788, 800, 818, 834, 854, 894,
]);
const CAMEROUN = 120;

const pct = (x) => Math.round(x * 1000) / 10;
const virgule = (x) => String(x).replace('.', ',');
const montant = (v) =>
  v >= 1e9 ? `${virgule((v / 1e9).toFixed(2))} Md$` : v >= 1e6 ? `${virgule((v / 1e6).toFixed(1))} M$` : `${Math.round(v / 1e3)} k$`;

// ---------- Brief : ce qu'il faut retenir et ce que tu peux en faire ----------
const p = $('Paramètres').first().json;
const fiches = Object.fromEntries(p.produits.map((x) => [x.hs, x]));
const paysParCode = Object.fromEntries(p.pays.map((x) => [x.code, x]));
const fcfa = (usd) => Math.round((usd * p.fcfaParDollar) / 5) * 5;
const de = (x) => (/^([aeiouyœéèêàâîôû]|huile)/i.test(x) ? `d'${x}` : `de ${x}`);

function aRetenir(o, total) {
  const tendance =
    o.croissance_annuelle_pct === ''
      ? ''
      : `, ${o.croissance_annuelle_pct >= 0 ? 'en hausse' : 'en baisse'} de ${virgule(Math.abs(o.croissance_annuelle_pct))} % par an`;
  let t = `${o.pays} : ${montant(o.imports_usd)} d'importations ${de(o.produit.toLowerCase())} en ${o.annee}${tendance}.`;
  if (o.prix_usd_kg !== '') t += ` Prix moyen à l'arrivée : ${virgule(o.prix_usd_kg)} $/kg, soit environ ${fcfa(o.prix_usd_kg)} FCFA/kg avant droits de douane et marges.`;
  if (total) {
    if (o.code_pays === CAMEROUN) {
      t += ` ${virgule(pct(1 - o.part_afrique_pct / 100))} % vient de l'extérieur de l'Afrique (${o.principaux_fournisseurs}).`;
    } else {
      t += ` Fournisseurs : ${o.principaux_fournisseurs}. L'Afrique fournit ${virgule(o.part_afrique_pct)} %, le Cameroun ${virgule(o.part_cameroun_pct)} %.`;
    }
  }
  if (o.donnees_anciennes === 'oui') t += ` Chiffres de ${o.annee} : à confirmer sur le terrain.`;
  return t;
}

// Un produit est « pour toi » s'il est adapté à Douala ET si son cycle respecte ta limite (ferme.cycleMaxMois)
const cycleOk = (f) => (f.cycleMois ?? 99) <= p.ferme.cycleMaxMois;
const tropLong = (f) => `cycle trop long pour toi (${f.delai}, au-delà de ${p.ferme.cycleMaxMois} mois)`;

function queFaire(o) {
  const f = fiches[o.code_hs] || { faisable: 'non' };
  const dans = paysParCode[o.code_pays]?.dans || `en ${o.pays}`;
  const pourMoi = f.faisable !== 'non' && cycleOk(f);
  const raison = f.faisable === 'non' ? f.note : !cycleOk(f) ? tropLong(f) : f.note;

  if (o.zone === 'Cameroun') {
    if (pourMoi && f.faisable === 'oui') {
      return {
        pour_ma_ferme: 'Projet possible',
        que_faire: `Tu peux remplacer une partie de ces importations depuis ta ferme : ${f.projet}. Premières ventes : ${f.delai}. Le produit importé arrive autour de ${o.prix_usd_kg !== '' ? fcfa(o.prix_usd_kg) + ' FCFA/kg' : 'un prix à vérifier'} : c'est le prix de ta concurrence avant droits et marges. Prochaine étape : ${f.etape}.`,
      };
    }
    if (pourMoi) {
      return {
        pour_ma_ferme: 'Possible, avec réserves',
        que_faire: `Faisable à ${p.ferme.lieu} mais pas idéal : ${f.note}. Projet possible : ${f.projet} (premières ventes : ${f.delai}). Autre piste : apporteur d'affaires entre les producteurs ${f.zone} et les grossistes de Douala.`,
      };
    }
    if (!f.zone) {
      return { pour_ma_ferme: 'À surveiller', que_faire: `Pas pour ta ferme : ${raison}. Rien à faire pour l'instant.` };
    }
    return {
      pour_ma_ferme: 'Courtage seulement',
      que_faire: `Pas pour ta ferme : ${raison}. Piste d'apporteur d'affaires : les grossistes de Douala achètent à l'étranger ; propose-leur des producteurs ${f.zone}, avec ta commission fixée par écrit.`,
    };
  }
  if (o.zone === 'Hors Afrique') {
    return {
      pour_ma_ferme: 'Plus tard (export)',
      que_faire: `Gros marché mais exigeant (normes, certificats${['1801', '0901'].includes(o.code_hs) ? ', traçabilité anti-déforestation pour l’Union européenne' : ''}). Pas pour démarrer. Pour l'instant : apporteur d'affaires auprès d'exportateurs agréés du Cameroun${pourMoi ? `, et débouché possible plus tard pour ton projet « ${f.projet} »` : ''}.`,
    };
  }
  // Afrique et CEMAC
  let accroche = '';
  if (o.part_afrique_pct !== '' && o.part_afrique_pct < 20) {
    accroche = `Ce pays achète presque tout hors d'Afrique : un fournisseur camerounais a un argument (proximité, ${o.zone === 'CEMAC' ? 'pas de droits de douane dans la CEMAC' : 'ZLECAf'}). `;
  } else if (o.part_afrique_pct !== '') {
    accroche = `Des fournisseurs africains sont déjà présents : il faudra être compétitif sur le prix. `;
  }
  if (pourMoi && f.faisable === 'oui') {
    return {
      pour_ma_ferme: 'Courtage maintenant, export plus tard',
      que_faire: `${accroche}Tout de suite : apporteur d'affaires entre des producteurs camerounais et des importateurs ${dans} (chambre de commerce, ambassade, plateformes B2B). Plus tard : débouché pour ton projet « ${f.projet} », une fois le marché de Douala maîtrisé.`,
    };
  }
  return {
    pour_ma_ferme: 'Courtage seulement',
    que_faire: `${accroche}Pas pour ta ferme (${raison || 'pas adapté à Douala'}), mais piste d'apporteur d'affaires : producteurs ${f.zone || 'camerounais'} vers des importateurs ${dans}.`,
  };
}

return top.map((item) => {
  const o = { ...item.json };
  const lignes = lignesFournisseurs.filter(
    (l) => l.reporterCode === o.code_pays && l.cmdCode === o.code_hs && l.refYear === o.annee,
  );

  // Une ligne par fournisseur (on garde la plus grosse si doublon)
  const parFournisseur = {};
  for (const l of lignes) {
    if (l.partnerCode === 0 || l.flowCode !== 'M' || !l.primaryValue) continue;
    const deja = parFournisseur[l.partnerCode];
    if (!deja || l.primaryValue > deja.primaryValue) parFournisseur[l.partnerCode] = l;
  }
  const liste = Object.values(parFournisseur).sort((a, b) => b.primaryValue - a.primaryValue);
  const total = liste.reduce((a, l) => a + l.primaryValue, 0);

  if (!total) {
    o.part_afrique_pct = '';
    o.part_cameroun_pct = '';
    o.principaux_fournisseurs = 'non disponible';
  } else {
    const afrique = liste
      .filter((l) => AFRIQUE.has(l.partnerCode) && l.partnerCode !== o.code_pays)
      .reduce((a, l) => a + l.primaryValue, 0);
    const cameroun = parFournisseur[CAMEROUN]?.primaryValue || 0;
    o.part_afrique_pct = pct(afrique / total);
    o.part_cameroun_pct = o.code_pays === CAMEROUN ? '' : pct(cameroun / total);
    o.principaux_fournisseurs = liste
      .slice(0, 3)
      .map((l) => `${noms[String(l.partnerCode)] || 'Pays ' + l.partnerCode} ${Math.round((100 * l.primaryValue) / total)} %`)
      .join(', ');

    // Prix moyen au kilo, si la ligne « monde » ne le donnait pas
    if (o.prix_usd_kg === '') {
      const avecPoids = liste.filter((l) => l.netWgt > 0);
      const poids = avecPoids.reduce((a, l) => a + l.netWgt, 0);
      if (poids) o.prix_usd_kg = Math.round((avecPoids.reduce((a, l) => a + l.primaryValue, 0) / poids) * 100) / 100;
    }
  }

  o.a_retenir = aRetenir(o, total);
  Object.assign(o, queFaire(o));
  return { json: o };
});

// Met en forme l'email du mois : une fiche par opportunité, avec ce qu'il faut retenir et ce que tu peux en faire.
const p = $('Paramètres').first().json;
const lignes = $input.all().map((i) => i.json);
const tous = $('Calculer les scores').all().map((i) => i.json);
const paysAvecDonnees = new Set(tous.map((r) => r.pays));
const paysSansDonnees = p.pays.filter((x) => !paysAvecDonnees.has(x.nom)).map((x) => x.nom);

// Requêtes refusées (quota de la version gratuite) : les chiffres peuvent être incomplets
const echecs = [...$('Comtrade : importations').all(), ...$('Comtrade : qui fournit ?').all()].filter(
  (r) => !Array.isArray(r.json.data),
).length;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const COULEURS = {
  'Projet possible': ['#1f7a4d', '#def0e5'],
  'Possible, avec réserves': ['#9a6410', '#f6ead3'],
  'Courtage maintenant, export plus tard': ['#3346a8', '#e2e6f8'],
  'Courtage seulement': ['#3346a8', '#e2e6f8'],
  'Plus tard (export)': ['#5f6b69', '#e8eceb'],
  'À surveiller': ['#5f6b69', '#e8eceb'],
};

const fiche = (o, i) => {
  const [fg, bg] = COULEURS[o.pour_ma_ferme] || ['#5f6b69', '#e8eceb'];
  return `
  <div style="border:1px solid #e3e8e6;border-radius:10px;padding:12px 14px;margin:0 0 12px">
    <div style="margin:0 0 6px">
      <span style="font-weight:700">${i + 1}. ${esc(o.produit)} → ${esc(o.pays)}</span>
      <span style="display:inline-block;margin-left:6px;padding:2px 8px;border-radius:999px;font-size:12px;font-weight:600;color:${fg};background:${bg}">${esc(o.pour_ma_ferme)}</span>
      <span style="color:#8a9895;font-size:12px;margin-left:6px">score ${o.score}</span>
    </div>
    <div style="font-size:14px;margin:0 0 6px"><b>À retenir :</b> ${esc(o.a_retenir)}</div>
    <div style="font-size:14px"><b>Que faire :</b> ${esc(o.que_faire)}</div>
  </div>`;
};

const POUR_LA_FERME = ['Projet possible', 'Possible, avec réserves'];
const pourLaFerme = lignes.filter((o) => POUR_LA_FERME.includes(o.pour_ma_ferme));
const autres = lignes.filter((o) => !POUR_LA_FERME.includes(o.pour_ma_ferme));

const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;color:#13201e;max-width:760px">
  <h2 style="margin:0 0 4px">Radar commerce Afrique : ${lignes.length} pistes ce mois-ci</h2>
  <p style="margin:0 0 16px;color:#5a6a67">Pour ta ferme de ${p.ferme.surfaceHa} ha à ${esc(p.ferme.lieu)}, en cycles courts (${p.ferme.cycleMaxMois} mois maximum). Chaque piste dit ce qu'il faut retenir et ce que tu peux en faire. Tableau complet : <a href="${esc(p.googleSheetUrl)}">ta Google Sheet</a>, onglet « Opportunites ».</p>
  ${echecs ? `<p style="background:#fbf0d9;border-radius:8px;padding:10px 12px;margin:0 0 16px;font-size:14px"><b>${echecs} requête(s) ONU Comtrade refusée(s)</b> (quota de la version gratuite, rechargé toutes les 10 minutes). Certains chiffres peuvent manquer : relance le workflow dans 10 minutes.</p>` : ''}
  ${pourLaFerme.length ? `<h3 style="margin:8px 0 10px">Pour ta ferme (${pourLaFerme.length})</h3>${pourLaFerme.map(fiche).join('')}` : ''}
  ${autres.length ? `<h3 style="margin:20px 0 10px">Courtage et export (${autres.length})</h3>${autres.map((o, i) => fiche(o, pourLaFerme.length + i)).join('')}` : ''}
  ${paysSansDonnees.length ? `<p style="font-size:13px;color:#5a6a67;margin-top:16px">Pays sans chiffres récents chez ONU Comtrade (leurs douanes ne publient pas ou en retard) : ${esc(paysSansDonnees.join(', '))}. Pour eux, appuie-toi sur la veille quotidienne et les contacts terrain.</p>` : ''}
  <p style="font-size:12px;color:#8a9895;margin-top:16px">Source : ONU Comtrade (données officielles des douanes, publiées avec 1 à 2 ans de retard). Prix en FCFA au taux de ${p.fcfaParDollar} FCFA pour 1 $. Une piste est à vérifier sur le terrain, ce n'est pas une commande.</p>
</div>`;

const mois = $now.setLocale('fr').toFormat('LLLL yyyy');
return [{ json: { sujet: `Radar commerce Afrique : ${pourLaFerme.length} piste(s) pour ta ferme et ${autres.length} pistes de courtage ou d'export (${mois})`, html } }];
